-- Infographics generated by the chat agent (PNG stored in ObjectStorage).
CREATE TABLE "infographic_assets" (
    "id" UUID NOT NULL,
    "tenant_id" UUID NOT NULL,
    "title" TEXT NOT NULL,
    "template" TEXT NOT NULL,
    "mime" TEXT NOT NULL,
    "storage_key" TEXT NOT NULL,
    "byte_size" INTEGER NOT NULL,
    "width" INTEGER NOT NULL,
    "height" INTEGER NOT NULL,
    "created_by" UUID,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "infographic_assets_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "infographic_assets_tenant_id_created_at_idx" ON "infographic_assets"("tenant_id", "created_at");

ALTER TABLE "infographic_assets" ADD CONSTRAINT "infographic_assets_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE ON UPDATE CASCADE;
